class Livro extends Produto {
    private String autor;
    private String isbn;

    public Livro(String nome, double preco, String codigoBarras, String autor, String isbn) {
        super(nome, preco, codigoBarras);
        this.autor = autor;
        this.isbn = isbn;
    }

    @Override
    public void exibirDetalhes() {
        super.exibirDetalhes();
        System.out.println("Autor: " + autor);
        System.out.println("ISBN: " + isbn);
    }
}

class Produto {
    protected String nome;
    protected double preco;
    protected String codigoBarras;

    public Produto(String nome, double preco, String codigoBarras) {
        this.nome = nome;
        this.preco = preco;
        this.codigoBarras = codigoBarras;
    }

    public void exibirDetalhes() {
        System.out.println("Nome: " + nome);
        System.out.println("Preço: R$ " + preco);
        System.out.println("Código de Barras: " + codigoBarras);
    }
}

class Roupa extends Produto {
    private String tamanho;
    private String material;

    public Roupa(String nome, double preco, String codigoBarras, String tamanho, String material) {
        super(nome, preco, codigoBarras);
        this.tamanho = tamanho;
        this.material = material;
    }

    @Override
    public void exibirDetalhes() {
        super.exibirDetalhes();
        System.out.println("Tamanho: " + tamanho);
        System.out.println("Material: " + material);
    }
}
